use dib_verus::{Decoded, Mode, TryError as DibTryError};
use vstd::prelude::*;

pub mod ico;

verus! {

// Skeleton: proves the cross-crate DIB contract is usable from this crate; the
// real ICO implementation and its `try_decode_with_steps_logged` call live in
// `crate::ico`. The frozen DIB `decode_with_steps` name is gone (decision D1);
// the logged entry point returns a `TryError`, and its non-`OutOfMemory` part
// satisfies DIB's `decode_mp_eq` on `fmt_part`.
pub fn skeleton(b: &[u8]) -> (r: Result<Decoded, DibTryError>)
    ensures
        !matches!(r, Err(DibTryError::OutOfMemory(_))) ==> dib_verus::dib::decode_mp_eq(
            dib_verus::dib::fmt_part(r),
            b@,
            Mode::IcoEntryDibSlack,
        ),
{
    let (r, _steps) = dib_verus::try_decode_with_steps(b, Mode::IcoEntryDibSlack);
    r
}

} // verus!
